corrected_code:
const express = require('express');
const db = require('../db');

const app = express();

app.get('/api/telemetry/errors/:exceptionSpanId', async (req, res) => {
  const { exceptionSpanId } = req.params;

  // Constrain error lookup strictly to the authenticated organization's services
  const errorEvent = await db('otel_exception_events')
    .join('monitored_services', 'otel_exception_events.service_name', '=', 'monitored_services.name')
    .where({
      'otel_exception_events.span_id': exceptionSpanId,
      'monitored_services.organization_id': req.user.organizationId
    })
    .first();

  if (!errorEvent) {
    return res.status(404).json({ error: 'Exception event not found or access denied' });
  }

  return res.json({
    spanId: errorEvent.span_id,
    traceId: errorEvent.trace_id,
    exceptionType: errorEvent.exception_type,
    stackTrace: errorEvent.stack_trace,
    environmentContext: errorEvent.env_vars_snapshot
  });
});

module.exports = app;
